CREATE TABLE "medusa_products" (
    "id" STRING NOT NULL,
    "title" STRING NOT NULL,
    "handle" STRING NOT NULL,
    "subtitle" STRING,
    "description" STRING,
    "is_giftcard" BOOL NOT NULL,
    "status" STRING NOT NULL,
    "thumbnail" STRING,
    "weight" FLOAT8,
    "length" FLOAT8,
    "height" FLOAT8,
    "width" FLOAT8,
    "origin_country" STRING,
    "hs_code" STRING,
    "mid_code" STRING,
    "material" STRING,
    "discountable" BOOL NOT NULL,
    "external_id" STRING,
    "metadata" JSONB,
    "type_id" STRING,
    "collection_id" STRING,
    "created_at" TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP NOT NULL,
    "deleted_at" TIMESTAMP,
    PRIMARY KEY ("id")
);




